import { AfterViewInit, Directive, ElementRef, Inject, Input, NgZone, OnDestroy, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

/**
 * Same vertical-parallax treatment as the recent-works cards: the host image is
 * scaled up so it overflows its (overflow: hidden) parent on every side, then
 * panned along Y as that parent crosses the viewport. The parent element is
 * used as both the gsap.context scope and the ScrollTrigger trigger, so this
 * only works when placed on an <img> whose immediate parent is the clipping
 * wrapper.
 */
@Directive({
	selector: 'img[appParallaxY]',
	standalone: true,
})
export class ParallaxYDirective implements AfterViewInit, OnDestroy {
	@Input() parallaxScale = 1.3;
	@Input() parallaxRange = 20;

	private ctx?: gsap.Context;

	constructor(
		private readonly el: ElementRef<HTMLImageElement>,
		private readonly ngZone: NgZone,
		@Inject(PLATFORM_ID) private readonly platformId: Object,
	) {}

	ngAfterViewInit(): void {
		if (!isPlatformBrowser(this.platformId)) {
			return;
		}

		const image = this.el.nativeElement;
		const trigger = image.parentElement;
		if (!trigger) {
			return;
		}

		this.ngZone.runOutsideAngular(() => {
			gsap.registerPlugin(ScrollTrigger);

			this.ctx = gsap.context(() => {
				gsap.set(image, { scale: this.parallaxScale, transformOrigin: '50% 50%' });

				gsap.fromTo(
					image,
					{ yPercent: -this.parallaxRange },
					{
						yPercent: this.parallaxRange,
						ease: 'none',
						scrollTrigger: {
							trigger,
							start: 'top bottom',
							end: 'bottom top',
							scrub: true,
						},
					},
				);

				// Wrapper has no explicit height in some layouts, so it can collapse
				// until the image loads and reports its natural size — refresh so the
				// trigger's cached start/end match the post-load layout.
				if (!image.complete) {
					image.addEventListener('load', () => ScrollTrigger.refresh(), { once: true });
				}
			}, trigger);
		});
	}

	ngOnDestroy(): void {
		this.ctx?.revert();
	}
}
